package com.bank.profiling;

import jdk.jfr.*;
import java.io.IOException;
import java.nio.file.Path;
import java.time.Duration;

public class JfrDemo {

    // ═══ Custom JFR event for banking ═══
    @Name("com.bank.TradeExecution")
    @Label("Trade Execution")
    @Description("Records trade execution timing")
    @Category({"Banking", "Trading"})
    static class TradeExecutionEvent extends Event {
        @Label("Trade ID") String tradeId;
        @Label("Symbol") String symbol;
        @Label("Amount") double amount;
        @Label("Duration (ms)") long durationMs;
    }

    // ═══ Record custom event ═══
    public static void executeTrade(String tradeId, String symbol, double amount) {
        TradeExecutionEvent event = new TradeExecutionEvent();
        event.begin();                        // start timing

        // Simulate trade execution
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }

        event.tradeId = tradeId;
        event.symbol = symbol;
        event.amount = amount;
        event.durationMs = 50;
        event.commit();                       // record the event to JFR
    }

    // ═══ Programmatic recording ═══
    public static void startRecording() throws IOException {
        try (var recording = new Recording(Configuration.getConfiguration("profile"))) {
            recording.setMaxAge(Duration.ofMinutes(5));
            recording.setMaxSize(100 * 1024 * 1024);  // 100MB max
            recording.start();

            // Application runs...
            executeTrade("TRD-001", "RELIANCE", 245050);
            executeTrade("TRD-002", "TCS", 176000);

            recording.stop();
            recording.dump(Path.of("banking-profile.jfr"));
        }
    }
}
