package com.bank.java8;

import org.junit.jupiter.api.Test;
import jdk.jfr.Event;
import jdk.jfr.Label;
import static org.assertj.core.api.Assertions.assertThat;

class JfrConceptTest {

    @Label("Settlement Completed")
    static class SettlementEvent extends Event {
        @Label("Trade Id") String tradeId;
        @Label("Millis") long millis;
    }

    @Test
    void customEventCarriesDomainData() {
        SettlementEvent e = new SettlementEvent();
        e.begin();
        e.tradeId = "TRD-001";
        e.millis = 42;
        e.end();          // would be committed to the recording in production

        assertThat(e.tradeId).isEqualTo("TRD-001");
        assertThat(e.millis).isEqualTo(42);
    }
}
